import { lazy, Suspense } from "react";
import type { TaskColorRamp, TaskItem, TaskStatusOption } from "../types";

/**
 * Lazy-embeds the full `<TaskCard>` (Tier C). Pass this to `renderTooltip`
 * for a rich hover card. `React.lazy` keeps task-card OUT of the bundle
 * unless a consumer actually wires this in — the default lightweight tooltip
 * pulls nothing. Same-category relative dynamic import (rewriter-safe).
 */
const LazyTaskCard = lazy(() =>
  import("../../task-card").then((m) => ({ default: m.TaskCard })),
);

export function CalendarFullCardTooltip({
  item,
  statusOptions,
  colorRamp,
}: {
  item: TaskItem;
  statusOptions?: TaskStatusOption[];
  colorRamp?: TaskColorRamp;
}) {
  return (
    <div className="w-72">
      <Suspense
        fallback={
          <div className="p-3 text-xs text-muted-foreground">Loading…</div>
        }
      >
        <LazyTaskCard
          value={item}
          statusOptions={statusOptions}
          colorRamp={colorRamp}
        />
      </Suspense>
    </div>
  );
}

"use client";

import { useMemo } from "react";
import { format } from "date-fns";
import { Pencil, Trash2, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import { useCalendar } from "../hooks/use-calendar-context";
import { useCalendarEditOptional } from "../hooks/use-calendar-edit-extension";
import { coveredDays } from "../lib/segments";
import type { CalendarOccurrence } from "../types";

/**
 * Selected-event inspector (Tier B). Shows a read-only preview of the selected
 * occurrence; when the editing extension is wired, an Edit button reveals the
 * shared `edit.components.EventEditorPanel` (the full lazy `<TaskCard editable>`
 * — title, status, priority, dates, description) whose edits splice back via
 * `applyEditedSubtree`, plus Delete. Lives inside `EventCalendarRoot` (reads
 * context). Place it beside the views for a persistent details panel, or omit
 * it (the editor also surfaces via the `EditOverlays` component the assembly
 * mounts when there's no inspector).
 */

function whenLabel(occ: CalendarOccurrence): string {
  const s = new Date(occ.startMs);
  if (occ.kind === "milestone") return format(s, "PPP 'at' p");
  if (occ.allDay) {
    const last = new Date(coveredDays(occ).lastMs);
    return format(s, "yyyy-MM-dd") === format(last, "yyyy-MM-dd")
      ? `${format(s, "PPP")} (all day)`
      : `${format(s, "PPP")} – ${format(last, "PPP")}`;
  }
  return `${format(s, "PPP")} · ${format(s, "p")} – ${format(new Date(occ.endMs), "p")}`;
}

export function CalendarEventInspector({ className }: { className?: string }) {
  const { occurrences, selectedId, select, statusOptions, priorityOptions, labelOptions } =
    useCalendar();
  const edit = useCalendarEditOptional();

  const occ = useMemo(
    () => occurrences.find((o) => o.id === selectedId) ?? null,
    [occurrences, selectedId],
  );

  if (!occ) {
    return (
      <div
        className={cn(
          "flex flex-col items-center justify-center gap-1 p-6 text-center",
          className,
        )}
      >
        <p className="text-sm font-medium text-muted-foreground">
          No event selected
        </p>
        <p className="text-xs text-muted-foreground">
          Click an event to see its details{edit ? " and edit it" : ""}.
        </p>
      </div>
    );
  }

  const item = occ.item;
  const editingThis = edit?.editingId === item.id;
  const status = statusOptions?.find((o) => o.value === item.status);
  const priority = priorityOptions?.find((o) => o.value === item.priority);
  const canEdit = !!edit && edit.can("editDetails", item);
  const canDelete = !!edit && edit.can("delete", item);

  return (
    <div className={cn("flex flex-col gap-3 p-3", className)}>
      <div className="flex items-center justify-between gap-2">
        <span className="inline-flex items-center gap-2 text-xs font-medium uppercase tracking-wide text-muted-foreground">
          <span
            className="size-2 rounded-full"
            style={{ background: occ.color.fill }}
            aria-hidden
          />
          Event details
        </span>
        <button
          type="button"
          aria-label="Clear selection"
          onClick={() => select(null)}
          className="rounded-sm p-0.5 text-muted-foreground hover:bg-muted hover:text-foreground"
        >
          <X className="size-4" />
        </button>
      </div>

      {editingThis && edit ? (
        <edit.components.EventEditorPanel
          item={item}
          statusOptions={statusOptions}
          priorityOptions={priorityOptions}
          labelOptions={labelOptions}
          permissions={edit.permissions}
          onChange={edit.applyEditedSubtree}
          onDone={edit.closeEditor}
        />
      ) : (
        <>
          <div className="space-y-1">
            <h3 className="text-base font-semibold leading-tight text-foreground">
              {item.name}
            </h3>
            <p className="text-xs text-muted-foreground">{whenLabel(occ)}</p>
          </div>

          <div className="flex flex-wrap gap-1.5">
            {status ? (
              <Badge variant={status.variant ?? "secondary"}>
                {status.label}
              </Badge>
            ) : null}
            {priority ? (
              <Badge
                variant="outline"
                style={
                  priority.color
                    ? { color: priority.color, borderColor: priority.color }
                    : undefined
                }
              >
                {priority.label}
              </Badge>
            ) : null}
            {occ.overdue ? <Badge variant="destructive">Overdue</Badge> : null}
          </div>

          {item.description ? (
            <p className="whitespace-pre-wrap text-sm leading-relaxed text-foreground/80">
              {item.description}
            </p>
          ) : null}

          {edit ? (
            <div className="mt-1 flex gap-2">
              <Button
                size="sm"
                className="gap-1.5"
                disabled={!canEdit}
                onClick={() => edit.openEditor(item.id)}
              >
                <Pencil className="size-3.5" /> Edit
              </Button>
              <Button
                size="sm"
                variant="outline"
                className="gap-1.5"
                disabled={!canDelete}
                onClick={() => {
                  edit.deleteItem(item.id);
                  select(null);
                }}
              >
                <Trash2 className="size-3.5" /> Delete
              </Button>
            </div>
          ) : null}
        </>
      )}
    </div>
  );
}

"use client";

import { Skeleton } from "@/components/ui/skeleton";
import { cn } from "@/lib/utils";

/** Loading skeleton (Tier C). A month-grid placeholder. */
export function CalendarSkeleton({ className }: { className?: string }) {
  return (
    <div className={cn("flex flex-col gap-3 p-3", className)}>
      <div className="flex items-center justify-between">
        <Skeleton className="h-8 w-44" />
        <Skeleton className="h-8 w-52" />
      </div>
      <div className="grid grid-cols-7 gap-1">
        {/* 42 = 6 weeks × 7 — a month grid can return 6 rows, so reserve the max
            to avoid a load→loaded layout jump (monthGrid is 5 or 6 weeks). */}
        {Array.from({ length: 42 }).map((_, i) => (
          <Skeleton key={i} className="h-20 w-full" />
        ))}
      </div>
    </div>
  );
}
